'use strict';
// Focused independent review UI checks execute the shipped interface.
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),crypto=require('node:crypto');
const source=fs.readFileSync(path.join(__dirname,'../agent-operations-command-center.js'),'utf8');
class Element{
 constructor(tag='div'){this.tag=tag;this.value='';this.textContent='';this.children=[];this.dataset={};this.style={};this.disabled=false;this.hidden=false;this.checked=false;this.open=false;this.listeners={};}
 append(...items){this.children.push(...items);}replaceChildren(...items){this.children=items;}
 setAttribute(name,value){this.attributes??={};this.attributes[name]=String(value);}getAttribute(name){return this.attributes?.[name]??null;}
 addEventListener(type,listener){(this.listeners[type]??=[]).push(listener);}
 async emit(type,event={preventDefault(){}}){for(const listener of this.listeners[type]||[])await listener(event);}
 querySelectorAll(selector){const all=this.children.flatMap(x=>[x,...x.querySelectorAll('*')]),parts=selector.split(',');return all.filter(x=>parts.some(p=>p==='*'||p==='details[open]'?p==='*'||x.tag==='details'&&x.open:x.tag===p));}
}
const contents=e=>[e.textContent,...e.children.map(contents)].join(' ');
function state(revision=1,{ownerHash='a'.repeat(64),workspaceHash='b'.repeat(64),plans=[]}={}){return{
 version:'internal-operations-v1',revision,at:1700000000000+revision,runtime:{sourceCommit:'c'.repeat(40),release:{digest:'d'.repeat(64)}},scopeIdentity:{ownerHash,workspaceHash},plans,incidents:[],audit:[],permissions:{paidExecution:false,writesEnabled:false},reviewPolicy:{},organization:{templates:[{id:'budget-audit',name:'Budget report',department:'finance-operations'}],departments:[]},monitoring:{status:'observed-r'+revision,budget:{retainedMicros:10600000,pendingMicros:2200000,remainingMicros:4400000},activity:[],attribution:[],alerts:[],dependencies:{provider:{status:'unknown'}}}
};}
function plan(revision=1){return{id:'op_existing',revision,status:'queued',objective:'Existing zero-provider plan',priority:'normal',modelCalls:0,tasks:[{id:'op_existing_one',template:'budget-audit',department:'finance-operations',role:'finance-cost-control',status:'queued',dependsOn:[],recoveryCount:0}]};}
const draftInput=idempotencyKey=>({idempotencyKey,objective:'Cached bounded internal assignment.',priority:'normal',durationMs:600000,subtasks:[{key:'task1',template:'budget-audit',dependsOn:[]}]});
function harness(reply,storage=new Map()){
 const elements=new Map(),calls=[],intervals=[],get=id=>{const search=e=>e.id===id?e:e.children.map(search).find(Boolean);for(const e of elements.values()){const found=search(e);if(found)return found;}if(!elements.has(id))elements.set(id,new Element(id==='opsForm'?'form':['opsRefresh','opsCreate','opsEmergency','opsSync','opsRetry','opsEngineeringPreset'].includes(id)?'button':id==='opsObjective'?'textarea':id==='opsPriority'||id==='opsSequence'?'select':'div'));return elements.get(id);};
 get('opsObjective').value='Read owned internal records.';get('opsPriority').value='normal';get('opsSequence').value='ordered';
 get('agentOpsCommandCenter').querySelectorAll=selector=>[...elements.values()].filter(e=>e!==get('agentOpsCommandCenter')).concat(get('agentOpsCommandCenter').children).flatMap(e=>[e,...e.querySelectorAll(selector)]).filter(e=>selector.split(',').includes(e.tag));
 const context={window:{},document:{getElementById:get,createElement:tag=>new Element(tag)},crypto:crypto.webcrypto,AbortSignal,TextEncoder,Date,setInterval:fn=>intervals.push(fn),sessionStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)},fetch:async(url,options)=>{assert.equal(url,'/api/agent-operations');assert.equal(options.credentials,'same-origin');assert.equal(options.redirect,'error');const body=options.method==='GET'?{method:'GET'}:JSON.parse(options.body);calls.push(body);const answer=await reply(body);return answer?.__response?{ok:false,status:answer.status,json:async()=>answer.body}:{ok:true,status:200,json:async()=>{if(answer?.__jsonFailure)throw SyntaxError('PRIVATE_JSON_MUST_NOT_RENDER');return answer?.__json?answer.value:answer?.__engineering?{engineeringActivation:answer.value}:{operatingSystem:answer};}};}};
 vm.runInNewContext(source,context);
 return{get,calls,storage,intervals,update:value=>context.window.CallerCoreOperations.update(value===null?null:{operatingSystem:value}),refresh:()=>get('opsRefresh').emit('click'),submit:async()=>{await get('opsForm').emit('submit');await new Promise(setImmediate);},retry:()=>get('opsRetry').emit('click'),run:()=>get('opsPlans').querySelectorAll('button').find(b=>b.textContent==='Run next internal task').emit('click')};
}
function proposalPlan(){const p=plan();p.status='completed';p.tasks[0]={...p.tasks[0],template:'engineering-propose',status:'completed'};return p;}
const reviewButton=h=>h.get('opsPlans').querySelectorAll('button').find(b=>b.textContent==='Inspect independent-review requirements');

test('Preview configuration controls journal only through the owner API and do not execute provider changes or inference',async()=>{const receipt={id:'refresh_'+'3'.repeat(32),status:'claimed',executionAuthorized:false},h=harness(async()=>({__engineering:true,value:receipt}));h.update(state());assert.match(contents(h.get('agentOpsCommandCenter')),/Credentials are never entered here/);h.get('opsEngineeringConfigurationInput').value=JSON.stringify({id:receipt.id});await h.get('opsEngineeringconfigurationStatus').emit('click');assert.equal(h.calls.length,1);assert.equal(h.calls[0].action,'operations-engineering-activation-configurationStatus');assert.deepEqual(h.calls[0].input,{id:receipt.id});assert.match(h.get('opsEngineeringConfigurationResult').textContent,/"executionAuthorized": false/);assert(!h.calls.some(c=>/run|activate|deploy|prepare/.test(c.action)));});

test('configuration receipt input refuses credential-like text before any request',async()=>{const h=harness(async()=>{throw Error('No call expected');});h.update(state());h.get('opsEngineeringConfigurationInput').value=JSON.stringify({CALLERCORE_AGENTOPS_OPENAI_API_KEY:'SYNTHETIC_NOT_A_REAL_KEY'});await h.get('opsEngineeringconfigurationClaim').emit('click');assert.equal(h.calls.length,0);assert.match(h.get('opsEngineeringConfigurationResult').textContent,/No automatic retry, configuration change or paid request occurred/);});

for(const code of ['ENG_CONFIG_CLEANUP','OPS_STORAGE_UNCONFIRMED','BROKER_STORAGE_UNCONFIRMED','ENG_PRIVATE_CUSTOMER_DATA','PRIVATE_TOKEN sk-proj-DO_NOT_DISPLAY'])test('configuration failure displays only allowlisted boundary code: '+code.split(' ')[0],async()=>{const id='refresh_'+'3'.repeat(32),h=harness(async()=>({__response:true,status:409,body:{code,error:'SECRET_PROVIDER_BODY',headers:{Authorization:'SECRET_HEADER'}}}));h.update(state());h.get('opsEngineeringConfigurationInput').value=JSON.stringify({id});await h.get('opsEngineeringconfigurationStatus').emit('click');const text=h.get('opsEngineeringConfigurationResult').textContent;if(['ENG_CONFIG_CLEANUP','OPS_STORAGE_UNCONFIRMED','BROKER_STORAGE_UNCONFIRMED'].includes(code))assert(text.includes('Code: '+code+'.'));else assert.doesNotMatch(text,/Code:|ENG_PRIVATE_CUSTOMER_DATA|PRIVATE_TOKEN|sk-proj-/);assert(text.includes('Intent: '+id+'.'));assert.doesNotMatch(text,/SECRET_PROVIDER_BODY|SECRET_HEADER/);assert.match(text,/No automatic retry/);assert.equal(h.calls.length,1);});

const configurationControls=['opsEngineeringDevelopmentPreset','opsEngineeringDevelopmentEnroll','opsEngineeringconfigurationClaim','opsEngineeringconfigurationStep','opsEngineeringconfigurationStatus','opsEngineeringconfigurationComplete','opsEngineeringConfigurationInput'];
test('configuration controls and receipt input recover only after owner state returns and after ordinary mutation refresh',async()=>{const h=harness(async b=>b.action==='operations-read'?state(3):{cancelled:true});h.update(null);for(const id of configurationControls)assert.equal(h.get(id).disabled,true,id);h.update(state());for(const id of configurationControls)assert.equal(h.get(id).disabled,false,id);await h.get('opsSync').emit('click');await new Promise(setImmediate);h.update(state(4));for(const id of configurationControls)assert.equal(h.get(id).disabled,false,id);assert(!h.calls.some(c=>/configuration|activation-run|activation-activate/.test(c.action)));});

test('configuration receipt completion restores textarea and controls after overlapping snapshot without extra action',async()=>{let finish;const h=harness(()=>new Promise(resolve=>finish=resolve));h.update(state());h.get('opsEngineeringConfigurationInput').value=JSON.stringify({id:'refresh_'+'3'.repeat(32)});const pending=h.get('opsEngineeringconfigurationStatus').emit('click');await new Promise(setImmediate);h.update(state(2));for(const id of configurationControls)assert.equal(h.get(id).disabled,true,id);finish({__engineering:true,value:{status:'claimed',executionAuthorized:false}});await pending;for(const id of configurationControls)assert.equal(h.get(id).disabled,false,id);assert.equal(h.calls.length,1);h.update(state(3,{workspaceHash:'f'.repeat(64)}));assert.doesNotMatch(h.get('opsEngineeringConfigurationResult').textContent,/"status": "claimed"/);});
test('review requirements button uses only guarded read, labels blocked submission and never promotes acceptance',async()=>{const bundle={version:'engineering-independent-review-v1',bindingHash:'e'.repeat(64),acceptedWork:false,publicationAuthorized:false,proposals:[{id:'p1',problem:'Source impact remains unverified.'}],dimensions:['problemSupport']},h=harness(async()=>bundle);h.update(state(1,{plans:[proposalPlan()]}));await reviewButton(h).emit('click');assert.equal(h.calls.length,1);assert.deepEqual(h.calls[0],{action:'operations-engineering-review-bundle',input:{planId:'op_existing',taskId:'op_existing_one'}});assert.match(contents(h.get('opsPlans')),/submission blocked until independent identity is verified/);assert.match(contents(h.get('opsPlans')),/"acceptedWork": false/);assert.match(contents(h.get('opsPlans')),/"publicationAuthorized": false/);assert(!h.calls.some(c=>/submit|attest|run|create/.test(c.action)));});
test('late review bundle cannot attach to different workspace or session-lost current view',async()=>{for(const scope of ['foreign','lost']){let done;const h=harness(()=>new Promise(r=>done=r));h.update(state(1,{plans:[proposalPlan()]}));const pending=reviewButton(h).emit('click');await new Promise(setImmediate);if(scope==='foreign')h.update(state(2,{workspaceHash:'f'.repeat(64),plans:[proposalPlan()]}));else h.update(null);done({secretMarker:'OLD_WORKSPACE_REVIEW',acceptedWork:false});await pending;assert.doesNotMatch(contents(h.get('opsPlans')),/OLD_WORKSPACE_REVIEW/);assert.equal(h.calls.length,1);}});
test('failed review request truthfully reports unavailable and cannot submit or grant authority',async()=>{const h=harness(async()=>{throw Error('Owner session denied');});h.update(state(1,{plans:[proposalPlan()]}));await reviewButton(h).emit('click');assert.match(h.get('opsStatus').textContent,/No review or acceptance was submitted/);assert.equal(h.calls.length,1);assert.equal(h.calls[0].action,'operations-engineering-review-bundle');});
test('hostile returned review strings render as plain text and contain no new executable action',async()=>{const h=harness(async()=>({reason:'<img src=x onerror=alert(1)>',publicationAuthorized:false}));h.update(state(1,{plans:[proposalPlan()]}));await reviewButton(h).emit('click');assert.match(contents(h.get('opsPlans')),/<img src=x onerror=alert\(1\)>/);assert.equal(h.get('opsPlans').querySelectorAll('img').length,0);assert.equal(h.calls.length,1);});
const reviewDetails=h=>h.get('opsPlans').querySelectorAll('details').find(d=>d.dataset.id?.endsWith('_review'));
test('safe non-2xx run receipt survives automatic snapshots and read refresh with no automatic retry',async()=>{const h=harness(async b=>b.action==='operations-run'?{__response:true,status:409,body:{code:'OPS_PLAN_STALE',error:'PRIVATE_PROVIDER_PAYLOAD'}}:state(3,{plans:[plan()]}));h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/operations-run.*OPS_PLAN_STALE/);assert.doesNotMatch(h.get('opsStatus').textContent,/PRIVATE_PROVIDER_PAYLOAD/);h.update(state(2,{plans:[plan()]}));assert.match(h.get('opsStatus').textContent,/OPS_PLAN_STALE/);await h.refresh();assert.match(h.get('opsStatus').textContent,/OPS_PLAN_STALE/);assert.equal(h.calls.filter(c=>c.action==='operations-run').length,1);assert.match(h.get('opsStatus').textContent,/not proof of backend failure/);});
function completedRunPlan(){const p=plan(3);p.status='completed';p.tasks[0]={...p.tasks[0],status:'completed',internalVerified:true,attempts:[{executionId:'internal_review_ui_fixture_001',status:'completed',resultHash:'e'.repeat(64),reviewHash:'f'.repeat(64)}]};return p;}
test('unsafe provider code falls back to HTTP status and explicit successful mutation clears old receipt',async()=>{let failure=true;const h=harness(async b=>b.action==='operations-run'&&failure?{__response:true,status:503,body:{code:'sk-proj-DO_NOT_EXPOSE',error:'RAW_SECRET'}}:b.action==='operations-run'?completedRunPlan():state(3,{plans:[completedRunPlan()]}));h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/HTTP_503/);assert.doesNotMatch(h.get('opsStatus').textContent,/DO_NOT_EXPOSE|RAW_SECRET/);h.update(state(2,{plans:[plan()]}));failure=false;await h.run();assert.doesNotMatch(h.get('opsStatus').textContent,/HTTP_503|Last unconfirmed action/);assert.match(h.get('opsStatus').textContent,/verified from persisted state/);});
test('network failure text never becomes a visible credential-bearing diagnostic',async()=>{const h=harness(async()=>{throw Error('SECRET_SESSION_COOKIE');});h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/REQUEST_UNCONFIRMED/);assert.doesNotMatch(h.get('opsStatus').textContent,/SECRET_SESSION_COOKIE/);h.update(null);h.update(state(2,{plans:[plan()]}));assert.doesNotMatch(h.get('opsStatus').textContent,/Last unconfirmed action/);});
test('review bundle persists through same-binding refresh and preserves explicit open and closed choices',async()=>{const h=harness(async()=>({acceptedWork:false,publicationAuthorized:false,marker:'BOUND_REVIEW'})),p=proposalPlan();p.tasks[0].revision=1;h.update(state(1,{plans:[p]}));await reviewButton(h).emit('click');assert.equal(reviewDetails(h).open,true);h.update(state(2,{plans:[structuredClone(p)]}));assert.match(contents(h.get('opsPlans')),/BOUND_REVIEW/);assert.equal(reviewDetails(h).open,true);reviewDetails(h).open=false;h.update(state(3,{plans:[structuredClone(p)]}));assert.equal(reviewDetails(h).open,false);assert.equal(h.calls.length,1);});
test('late same-binding bundle renders in current card after old card was replaced by automatic refresh',async()=>{let done;const h=harness(()=>new Promise(r=>done=r)),p=proposalPlan();p.tasks[0].revision=1;h.update(state(1,{plans:[p]}));const pending=reviewButton(h).emit('click');await new Promise(setImmediate);h.update(state(2,{plans:[structuredClone(p)]}));done({marker:'CURRENT_CARD_REVIEW'});await pending;assert.match(contents(h.get('opsPlans')),/CURRENT_CARD_REVIEW/);assert(reviewDetails(h));});
test('task revision and source replacement purge cached review and reject delayed stale responses',async()=>{for(const mode of ['revision','source']){let done;const h=harness(()=>new Promise(r=>done=r)),p=proposalPlan();p.tasks[0].revision=1;h.update(state(1,{plans:[p]}));const pending=reviewButton(h).emit('click');await new Promise(setImmediate);const next=state(2,{plans:[structuredClone(p)]});if(mode==='revision')next.plans[0].tasks[0].revision=2;else next.runtime.sourceCommit='f'.repeat(40);h.update(next);done({marker:'STALE_REVIEW'});await pending;assert.doesNotMatch(contents(h.get('opsPlans')),/STALE_REVIEW/);assert.equal(reviewDetails(h),undefined);}});
test('session loss then same-owner reauthentication does not revive a previous in-flight bundle',async()=>{let done;const h=harness(()=>new Promise(r=>done=r)),p=proposalPlan();h.update(state(1,{plans:[p]}));const pending=reviewButton(h).emit('click');await new Promise(setImmediate);h.update(null);h.update(state(2,{plans:[p]}));done({marker:'REVOKED_SESSION_REVIEW'});await pending;assert.doesNotMatch(contents(h.get('opsPlans')),/REVOKED_SESSION_REVIEW/);});
test('existing cached review disappears on task-binding change without new fetch or mutation',async()=>{const h=harness(async()=>({marker:'OLD_BOUND_REVIEW'})),p=proposalPlan();p.tasks[0].revision=1;h.update(state(1,{plans:[p]}));await reviewButton(h).emit('click');assert(reviewDetails(h));const next=structuredClone(p);next.tasks[0].revision=2;h.update(state(2,{plans:[next]}));assert.equal(reviewDetails(h),undefined);assert.doesNotMatch(contents(h.get('opsPlans')),/OLD_BOUND_REVIEW/);assert.equal(h.calls.length,1);});
test('observed deadline expiry is displayed and cannot expose Run while cleanup cancellation stays available',async()=>{const h=harness(async()=>{throw Error('No request expected');}),p=plan();p.observedStatus='deadline-expired';h.update(state(1,{plans:[p]}));assert.match(contents(h.get('opsPlans')),/deadline-expired/);assert.equal(h.get('opsPlans').querySelectorAll('button').some(b=>b.textContent==='Run next internal task'),false);assert.equal(h.get('opsPlans').querySelectorAll('button').some(b=>b.textContent==='Cancel assignment'&&!b.disabled),true);h.update(state(2,{plans:[structuredClone(p)]}));assert.equal(h.get('opsPlans').querySelectorAll('button').some(b=>b.textContent==='Run next internal task'),false);assert.equal(h.calls.length,0);});
test('failed authenticated refresh purges epoch before same-owner restore, dropping late previous review',async()=>{let done;const h=harness(b=>b.action==='operations-read'?{__response:true,status:401,body:{error:'Authentication required'}}:new Promise(r=>done=r)),p=proposalPlan();h.update(state(1,{plans:[p]}));const pending=reviewButton(h).emit('click');await new Promise(setImmediate);await h.refresh();h.update(state(2,{plans:[p]}));done({marker:'STALE_AFTER_401'});await pending;assert.doesNotMatch(contents(h.get('opsPlans')),/STALE_AFTER_401/);assert.equal(reviewDetails(h),undefined);});
test('HTTP 200 no-op run and unchanged readback never claim execution or automatically retry',async()=>{const h=harness(async b=>b.action==='operations-run'?{}:state(1,{plans:[plan()]}));h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/OPS_READBACK_UNCONFIRMED/);assert.doesNotMatch(h.get('opsStatus').textContent,/Operation verified/);h.update(state(2,{plans:[plan()]}));assert.match(h.get('opsStatus').textContent,/OPS_READBACK_UNCONFIRMED/);assert.equal(h.calls.filter(c=>c.action==='operations-run').length,1);});
test('run semantic receipt rejects wrong plan, missing execution, or unmatched persisted attempt hashes',async()=>{for(const mode of ['wrong-plan','no-attempt','wrong-hash','unchanged-plan']){const result=completedRunPlan(),persisted=completedRunPlan();if(mode==='wrong-plan')result.id='op_unrelated';if(mode==='no-attempt')result.tasks[0].attempts=[];if(mode==='wrong-hash')persisted.tasks[0].attempts[0].resultHash='a'.repeat(64);if(mode==='unchanged-plan')result.revision=persisted.revision=1;const h=harness(async b=>b.action==='operations-run'?result:state(3,{plans:[persisted]}));h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/OPS_READBACK_UNCONFIRMED/,mode);assert.doesNotMatch(h.get('opsStatus').textContent,/Operation verified/,mode);}});
test('successful run is confirmed only with returned new execution and matching persisted receipt',async()=>{const result=completedRunPlan(),h=harness(async b=>b.action==='operations-run'?result:state(3,{plans:[result]}));h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/Operation verified from persisted state/);assert.doesNotMatch(h.get('opsStatus').textContent,/UNCONFIRMED/);});
test('200 empty Create, Cancel, Sync and Emergency responses cannot produce verified status',async()=>{for(const action of ['create','cancel','sync','emergency']){const h=harness(async b=>b.action==='operations-read'?state(2,{plans:[plan()]}):{});h.update(state(1,{plans:[plan()]}));if(action==='create')await h.submit();if(action==='cancel')await h.get('opsPlans').querySelectorAll('button').find(b=>b.textContent==='Cancel assignment').emit('click');if(action==='sync')await h.get('opsSync').emit('click');if(action==='emergency')await h.get('opsEmergency').emit('click');await new Promise(setImmediate);assert.match(h.get('opsStatus').textContent,/OPS_READBACK_UNCONFIRMED/,action);assert.doesNotMatch(h.get('opsStatus').textContent,/Operation verified/,action);}});
test('valid Create, Cancel, Sync and Emergency receipts are confirmed against changed authoritative snapshots',async()=>{for(const action of ['create','cancel','sync','emergency']){let result,readback;const h=harness(async b=>{if(b.action==='operations-read')return readback;if(action==='create'){result={...plan(1),id:'op_new',idempotencyKey:b.input.idempotencyKey};readback=state(2,{plans:[result]});}if(action==='cancel'){result={...plan(2),status:'cancelled'};readback=state(2,{plans:[result]});}if(action==='sync'){result={incidents:[],observedAt:1700000000002};readback=state(2,{plans:[plan()]});}if(action==='emergency'){result={cancelled:true,modelCalls:0};readback=state(2,{plans:[{...plan(2),status:'cancelled'}]});}return result;});h.update(state(1,{plans:[plan()]}));if(action==='create')await h.submit();if(action==='cancel')await h.get('opsPlans').querySelectorAll('button').find(b=>b.textContent==='Cancel assignment').emit('click');if(action==='sync')await h.get('opsSync').emit('click');if(action==='emergency')await h.get('opsEmergency').emit('click');await new Promise(setImmediate);assert.match(h.get('opsStatus').textContent,/Operation verified from persisted state/,action);assert.doesNotMatch(h.get('opsStatus').textContent,/UNCONFIRMED/,action);}});
test('old last execution cannot be relabeled as new progress by inserting an unrelated earlier attempt',async()=>{const prior=completedRunPlan();prior.status='queued';prior.revision=1;const result=completedRunPlan();result.tasks[0].attempts.unshift({...result.tasks[0].attempts[0],executionId:'invented_earlier_attempt'});const h=harness(async b=>b.action==='operations-run'?result:state(3,{plans:[completedRunPlan()]}));h.update(state(1,{plans:[prior]}));await h.run();assert.match(h.get('opsStatus').textContent,/OPS_READBACK_UNCONFIRMED/);});
test('mutation readback from substituted application release cannot establish operation success',async()=>{const result=completedRunPlan(),readback=state(3,{plans:[result]});readback.runtime.sourceCommit='f'.repeat(40);const h=harness(async b=>b.action==='operations-run'?result:readback);h.update(state(1,{plans:[plan()]}));await h.run();assert.match(h.get('opsStatus').textContent,/OPS_READBACK_UNCONFIRMED/);});

const trialButton=(h,label)=>h.get('agentOpsCommandCenter').querySelectorAll('button').find(b=>b.textContent===label);
function trialState(revision=1){const v=state(revision);v.runtime.origin='https://my-ai-website-test-mohamtaj004bas-projects.vercel.app';v.runtime.deploymentId='dpl_test';v.plans=[{...plan(),id:'op_trial_ui',engineeringProfile:'engineering-inference-rehearsal-v1',objective:require('../lib/agent-operations-engineering-provider-v2').UNCERTAIN_TRIAL.objective,tasks:[{...plan().tasks[0],attempts:[]}]}];return v;}
const trialApproval=()=>({sourceCommit:'c'.repeat(40),contractHash:'d'.repeat(64),deploymentOrigin:'https://my-ai-website-test-mohamtaj004bas-projects.vercel.app',id:'pilot_ui_trial',workflowId:'wf_ui_trial'});
function uiManifest(){return{__engineering:true,value:{planId:'op_trial_ui',expectedRevision:1,approval:trialApproval()}};}
for(const phase of ['trial-manifest','prepare','activate','run'])test('delayed '+phase+' trial response cannot disclose stale consent or results after workspace change',async()=>{let done;const h=harness(async b=>{const method=b.action.replace('operations-engineering-activation-','');if(method===phase)return new Promise(r=>done=r);if(method==='trial-manifest')return uiManifest();return{__engineering:true,value:method==='prepare'?{record:{revision:1}}:method==='activate'?{revision:2}:{status:'revoked'}};});h.update(trialState());let pending=trialButton(h,'Prepare exact authorized engineering trial').emit('click');if(['activate','run'].includes(phase)){await pending;pending=trialButton(h,'Run authorized trial once').emit('click');}await new Promise(setImmediate);const next=trialState(2);next.scopeIdentity.workspaceHash='f'.repeat(64);h.update(next);done(phase==='trial-manifest'?{__engineering:true,value:{...uiManifest().value,marker:'PRIVATE_OLD_TRIAL'}}:{__engineering:true,value:phase==='prepare'?{record:{revision:1,marker:'PRIVATE_OLD_TRIAL'}}:phase==='activate'?{revision:2,marker:'PRIVATE_OLD_TRIAL'}:{marker:'PRIVATE_OLD_TRIAL'}});await pending;assert.doesNotMatch(h.get('opsEngineeringTrialResult').textContent,/PRIVATE_OLD_TRIAL/);if(phase==='trial-manifest')assert.equal(h.calls.some(c=>c.action.endsWith('-prepare')),false);if(phase==='activate')assert.equal(h.calls.some(c=>c.action.endsWith('-run')),false);if(phase!=='trial-manifest')assert(h.calls.some(c=>c.action.endsWith('-revoke')));});
test('prepared trial cannot run against a substituted immutable deployment origin',async()=>{const h=harness(async b=>b.action.endsWith('trial-manifest')?uiManifest():{__engineering:true,value:{record:{revision:1}}});h.update(trialState());await trialButton(h,'Prepare exact authorized engineering trial').emit('click');const next=trialState(2);next.runtime.origin='https://my-ai-website-other-mohamtaj004bas-projects.vercel.app';next.runtime.deploymentId='dpl_other';h.update(next);await trialButton(h,'Run authorized trial once').emit('click');assert.equal(h.calls.some(c=>c.action.endsWith('-activate')||c.action.endsWith('-run')),false);});

test('trial owner controls recover from unavailable and mutation-disabled state only after authoritative refresh',async()=>{const h=harness(async b=>b.action==='operations-read'?trialState(2):{cancelled:true,modelCalls:0});h.update(null);for(const id of ['opsEngineeringTrialPreset','opsEngineeringTrialPrepare','opsEngineeringTrialRun','opsEngineeringTrialRevoke'])assert.equal(h.get(id).disabled,true);h.update(trialState());for(const id of ['opsEngineeringTrialPreset','opsEngineeringTrialPrepare','opsEngineeringTrialRun','opsEngineeringTrialRevoke'])assert.equal(h.get(id).disabled,false);await h.get('opsSync').emit('click');await new Promise(setImmediate);h.update(trialState(3));for(const id of ['opsEngineeringTrialPreset','opsEngineeringTrialPrepare','opsEngineeringTrialRun','opsEngineeringTrialRevoke'])assert.equal(h.get(id).disabled,false);});
function sequenceState(){const v=trialState();v.plans[0].objective=require('../lib/agent-operations-proposal-copy').OBJECTIVE;return v;}
function sequenceManifest(){const m=uiManifest();m.value.approval.sequence={id:'sequence_'+'1'.repeat(32),attempt:1};return m;}

function expandedState(revision=1){const v=trialState(revision);v.plans[0].objective=require('../lib/agent-operations-proposal-copy').EXPANDED_OBJECTIVE;return v;}
function expandedManifest(sequenceId){const m=sequenceManifest();m.value.approval.sequence.id=sequenceId;m.value.approval.countPricing={authorizationId:'owner-expanded-engineering-5usd-v1'};return m;}
test('expanded preset is exact new objective and cannot revive historical journals or automatically spend',async()=>{const storage=new Map([['callercore-engineering-trial-once-v1','{"historical":true}'],['callercore-engineering-bounded-sequence-v1','{"consumed":true}'],['callercore-engineering-sequence-attempt-v1','{"consumed":true}']]),before=JSON.stringify([...storage]),h=harness(async()=>{throw Error('No request allowed');},storage);h.update(expandedState());await h.get('opsEngineeringExpandedPreset').emit('click');assert.equal(h.get('opsObjective').value,require('../lib/agent-operations-proposal-copy').EXPANDED_OBJECTIVE);assert.equal(JSON.stringify([...storage]),before);assert.equal(h.calls.length,0);});
test('expanded preparation persists distinct ID before registration, limits expiry to 24h, and never activates',async()=>{let h;h=harness(async b=>{if(b.action.endsWith('sequenceRegister')){const saved=JSON.parse(h.storage.get('callercore-engineering-expanded-5usd-v1'));assert.equal(saved.id,b.input.sequenceId);assert.equal(saved.registrationRequested,true);assert(b.input.expiresAt>Date.now()+86390000&&b.input.expiresAt<=Date.now()+86400000);return{__engineering:true,value:{status:'open'}};}if(b.action.endsWith('trial-manifest'))return expandedManifest(b.input.sequenceId);return{__engineering:true,value:{record:{revision:1}}};});h.update(expandedState());await h.get('opsEngineeringExpandedPreset').emit('click');await h.get('opsEngineeringTrialPrepare').emit('click');assert(h.storage.has('callercore-engineering-expanded-attempt-v1'));assert.equal(h.storage.has('callercore-engineering-sequence-attempt-v1'),false);assert.equal(h.calls.filter(b=>b.action.endsWith('sequenceRegister')).length,1);assert.equal(h.calls.some(b=>b.action.endsWith('-activate')||b.action.endsWith('-run')),false);});
test('expanded lost registration acknowledgement recovers by status only without second registration or paid call',async()=>{const h=harness(async b=>{if(b.action.endsWith('sequenceRegister'))throw Error('Acknowledgement lost');if(b.action.endsWith('sequenceStatus'))throw Error('Unknown registration');throw Error('Unexpected mutation');});h.update(expandedState());await h.get('opsEngineeringExpandedPreset').emit('click');await h.get('opsEngineeringTrialPrepare').emit('click');await h.get('opsEngineeringTrialPrepare').emit('click');assert.equal(h.calls.filter(b=>b.action.endsWith('sequenceRegister')).length,1);assert.equal(h.calls.filter(b=>b.action.endsWith('sequenceStatus')).length,1);assert.equal(h.calls.some(b=>b.action.endsWith('-activate')||b.action.endsWith('-run')||b.action.endsWith('trial-manifest')),false);});
test('expanded release enrollment is explicit, fresh-task scoped, and late stale acknowledgement cannot update local pin',async()=>{let done;const h=harness(async b=>{assert(b.action.endsWith('sequenceEnroll'));assert.deepEqual(Object.keys(b.input).sort(),['expectedRevision','planId','sequenceId']);return new Promise(r=>done=r);}),v=expandedState();h.update(v);await h.get('opsEngineeringExpandedPreset').emit('click');const prior={scope:v.scopeIdentity,id:'sequence_'+'8'.repeat(32),runtime:'prior-reviewed-runtime'};h.storage.set('callercore-engineering-expanded-5usd-v1',JSON.stringify(prior));assert.equal(h.calls.length,0);const pending=h.get('opsEngineeringExpandedEnroll').emit('click');await new Promise(setImmediate);const next=expandedState(2);next.runtime.sourceCommit='f'.repeat(40);h.update(next);done({__engineering:true,value:{enrolled:true}});await pending;assert.deepEqual(JSON.parse(h.storage.get('callercore-engineering-expanded-5usd-v1')),prior);assert.equal(h.calls.length,1);});
test('expanded confirmed explicit revocation archives one closed local attempt and leaves authoritative history untouched',async()=>{const h=harness(async()=>({__engineering:true,value:{status:'revoked',leaseUntil:0}})),v=expandedState(),saved={scope:v.scopeIdentity,input:{planId:v.plans[0].id,expectedRevision:1,approval:{...trialApproval(),sequence:{id:'sequence_'+'8'.repeat(32),attempt:1},countPricing:{authorizationId:'owner-expanded-engineering-5usd-v1'}}},requested:true};h.update(v);await h.get('opsEngineeringExpandedPreset').emit('click');h.storage.set('callercore-engineering-expanded-attempt-v1',JSON.stringify(saved));h.storage.set('callercore-engineering-sequence-attempt-v1','historical consumed record');await h.get('opsEngineeringTrialRevoke').emit('click');assert.equal(h.storage.has('callercore-engineering-expanded-attempt-v1'),false);const archive=JSON.parse(h.storage.get('callercore-engineering-expanded-attempt-v1-history'));assert.deepEqual(archive[0].saved,saved);assert.equal(archive[0].revocation.status,'revoked');assert.equal(h.storage.get('callercore-engineering-sequence-attempt-v1'),'historical consumed record');assert.equal(h.calls.length,1);assert(h.calls[0].action.endsWith('-revoke'));assert.match(h.get('opsEngineeringTrialResult').textContent,/authoritative evidence remains/);});
test('expanded denied or nonterminal revocation never clears current recovery state or enables another attempt',async()=>{for(const value of [{status:'active',leaseUntil:0},{status:'revoked',leaseUntil:1},null]){const h=harness(async()=>value?{__engineering:true,value}:{__response:true,status:409,body:{error:'denied'}}),v=expandedState(),saved={scope:v.scopeIdentity,input:{planId:v.plans[0].id,approval:{...trialApproval(),countPricing:{authorizationId:'owner-expanded-engineering-5usd-v1'}}},requested:true};h.update(v);await h.get('opsEngineeringExpandedPreset').emit('click');const original=JSON.stringify(saved);h.storage.set('callercore-engineering-expanded-attempt-v1',original);await h.get('opsEngineeringTrialRevoke').emit('click');assert.equal(h.storage.get('callercore-engineering-expanded-attempt-v1'),original);assert.equal(h.storage.has('callercore-engineering-expanded-attempt-v1-history'),false);assert.equal(h.calls.length,1);}});
test('bounded sequence selection uses exact copy objective without provider dispatch',async()=>{const h=harness(async()=>{});h.update(sequenceState());await trialButton(h,'Select bounded sequence admission').emit('click');assert.equal(h.get('opsObjective').value,require('../lib/agent-operations-proposal-copy').OBJECTIVE);assert.equal(h.calls.length,0);});
test('bounded preparation durably saves registration ID before request and isolates consumed historical trial',async()=>{let h;h=harness(async b=>{if(b.action.endsWith('sequenceRegister')){const saved=JSON.parse(h.storage.get('callercore-engineering-bounded-sequence-v1'));assert.equal(saved.id,b.input.sequenceId);assert.equal(saved.registrationRequested,true);return{__engineering:true,value:{status:'open'}};}if(b.action.endsWith('trial-manifest')){assert.match(b.input.sequenceId,/^sequence_[a-f0-9]{32}$/);const m=sequenceManifest();m.value.approval.sequence.id=b.input.sequenceId;return m;}return{__engineering:true,value:{record:{revision:1}}};});h.update(sequenceState());h.storage.set('callercore-engineering-trial-once-v1',JSON.stringify({requested:true,historical:true}));await trialButton(h,'Select bounded sequence admission').emit('click');await trialButton(h,'Prepare exact authorized engineering trial').emit('click');assert.equal(h.calls.filter(b=>b.action.endsWith('sequenceRegister')).length,1);assert.equal(h.calls.some(b=>b.action.endsWith('-run')||b.action.endsWith('-activate')),false);assert.equal(JSON.parse(h.storage.get('callercore-engineering-trial-once-v1')).historical,true);assert(h.storage.has('callercore-engineering-sequence-attempt-v1'));});
test('lost sequence registration acknowledgment is never automatically resubmitted',async()=>{const h=harness(async b=>{if(b.action.endsWith('sequenceRegister'))throw Error('lost delivery');if(b.action.endsWith('sequenceStatus'))throw Error('not confirmed');throw Error('unexpected downstream action');});h.update(sequenceState());await trialButton(h,'Select bounded sequence admission').emit('click');await trialButton(h,'Prepare exact authorized engineering trial').emit('click');await trialButton(h,'Prepare exact authorized engineering trial').emit('click');assert.equal(h.calls.filter(b=>b.action.endsWith('sequenceRegister')).length,1);assert.equal(h.calls.filter(b=>b.action.endsWith('sequenceStatus')).length,1);assert.equal(h.calls.some(b=>b.action.endsWith('trial-manifest')),false);});
test('bounded stop uses owner recovery ID only and suppresses foreign workspace or delayed output',async()=>{let finish;const h=harness(async b=>{assert(b.action.endsWith('sequenceStop'));assert.deepEqual(Object.keys(b.input),['sequenceId']);return new Promise(resolve=>finish=resolve);});const v=sequenceState();h.update(v);h.storage.set('callercore-engineering-bounded-sequence-v1',JSON.stringify({scope:v.scopeIdentity,id:'sequence_'+'1'.repeat(32),runtime:JSON.stringify(v.runtime)}));const waiting=trialButton(h,'Stop bounded sequence').emit('click');await new Promise(setImmediate);const next=sequenceState();next.scopeIdentity.workspaceHash='f'.repeat(64);h.update(next);finish({__engineering:true,value:{marker:'OLD_PRIVATE_SEQUENCE'}});await waiting;assert.doesNotMatch(h.get('opsEngineeringTrialResult').textContent,/OLD_PRIVATE_SEQUENCE/);await trialButton(h,'Stop bounded sequence').emit('click');assert.equal(h.calls.length,1);});


for(const code of ['ENG_CONTROL_AUDIT_CAPACITY','ENG_CONTROL_LEDGER_CAPACITY','ENG_CONTROL_CONCURRENT_STATE'])test('configuration UI preserves finite capacity classification with safe receipt correlation: '+code,async()=>{const id='refresh_'+'3'.repeat(32),h=harness(async()=>({__response:true,status:409,body:{code,error:'SECRET_PRIVATE_PROVIDER_BODY'}}));h.update(state());h.get('opsEngineeringConfigurationInput').value=JSON.stringify({id});await h.get('opsEngineeringconfigurationStatus').emit('click');const text=h.get('opsEngineeringConfigurationResult').textContent;assert(text.includes('Code: '+code+'.'));assert(text.includes('Intent: '+id+'.'));assert.doesNotMatch(text,/SECRET_PRIVATE_PROVIDER_BODY/);assert.match(text,/No automatic retry/);assert.equal(h.calls.length,1);});

