for(const phase of ['sequenceRegister','sequenceStatus','trial-manifest','prepare'])test('preparation denial retains safe phase without retry or private response: '+phase,async()=>{
 const h=harness(async b=>{const method=b.action.replace('operations-engineering-activation-','');if(method===phase)return{__response:true,status:409,body:{code:'ENG_SEQUENCE_EXPOSURE',error:'SECRET_PROVIDER_BODY',headers:{Authorization:'SECRET_HEADER'}}};if(method==='trial-manifest')return expandedManifest(b.input.sequenceId);return{__engineering:true,value:{status:'revoked',record:{revision:1}}};});
 const v=expandedState();h.update(v);await h.get('opsEngineeringExpandedPreset').emit('click');if(phase==='sequenceStatus')h.storage.set('callercore-engineering-expanded-5usd-v1',JSON.stringify({scope:v.scopeIdentity,runtime:JSON.stringify(v.runtime),id:'sequence_'+'1'.repeat(32)}));
 await h.get('opsEngineeringTrialPrepare').emit('click');const text=h.get('opsEngineeringTrialResult').textContent;assert(text.includes('Phase: '+phase+'.'));assert(text.includes('Code: ENG_SEQUENCE_EXPOSURE.'));assert.doesNotMatch(text,/SECRET_PROVIDER_BODY|SECRET_HEADER/);assert.match(text,/Do not repeat/);assert.equal(h.calls.filter(b=>b.action.endsWith('-'+phase)).length,1);assert.equal(h.calls.some(b=>b.action.endsWith('-run')||b.action.endsWith('-activate')),false);
});
test('untrusted preparation error codes never enter diagnostics',async()=>{const h=harness(async()=>({__response:true,status:403,body:{code:'PRIVATE_TOKEN sk-proj-NEVER_DISPLAY',error:'SECRET'}}));h.update(expandedState());await h.get('opsEngineeringExpandedPreset').emit('click');await h.get('opsEngineeringTrialPrepare').emit('click');assert.match(h.get('opsEngineeringTrialResult').textContent,/ENG_PREPARATION_UNCONFIRMED/);assert.doesNotMatch(h.get('opsEngineeringTrialResult').textContent,/PRIVATE_TOKEN|sk-proj-|SECRET/);assert.equal(h.calls.length,1);});
function recoveryPayload(){const current=state();current.runtime={origin:'https://my-ai-website-current-mohamtaj004bas-projects.vercel.app',sourceCommit:'e'.repeat(40),branch:'feature/callercore-dashboards',deploymentId:'dpl_current',release:{version:'organization-contracts-v4',digest:'f'.repeat(64)}};const target={origin:'https://my-ai-website-target-mohamtaj004bas-projects.vercel.app',sourceCommit:'c'.repeat(40),branch:'feature/callercore-dashboards',deploymentId:'dpl_target',release:{version:'organization-contracts-v4',digest:'d'.repeat(64)}},row={version:'engineering-cumulative-sequence-v3',id:'sequence_'+'1'.repeat(32),status:'open',authorizationId:'owner-phase-d-engineering-4usd-v1',authorizationBudgetId:'owner-expanded-engineering-5usd-v1',createdAt:Date.now()-1000,expiresAt:Date.now()+3600000,remainingMicros:2600000,maxAttempts:10,maxMicros:4000000,attemptMicros:1000000,providerHardCap:false,bindingHash:'2'.repeat(64),runtime:target,attempts:[],executionAuthorized:false,enrollments:[{ordinal:1,previousHash:null,at:Date.now()-500,hash:'3'.repeat(64),bindingHash:'2'.repeat(64),configurationIntentId:'refresh_'+'4'.repeat(32),configurationHash:'5'.repeat(64),runtime:structuredClone(target)}]};return{operatingSystem:current,ownerPilotControl:{version:'owner-pilot-control-v1',paidExecution:false,configured:null,approvals:[],workflows:[],cleanupStatus:{ready:true,executionAuthorized:false,cleanupContractSatisfied:true,blockers:[],revocationTargets:[],unattributedBlockers:0,ownedGrants:[],snapshotHash:'6'.repeat(64),observedAt:1},engineeringSequences:[row]}};}
test('explicit recovery uses two GETs and stores exact older target selection without changing mode or dispatching POST',async()=>{const payload=recoveryPayload(),storage=new Map(),h=harness(async body=>{assert.equal(body.method,'GET');return{__json:true,value:structuredClone(payload)};},storage);h.update(payload.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.calls.length,2);assert(h.calls.every(x=>x.method==='GET'));const saved=JSON.parse(storage.get('callercore-engineering-development-4usd-v1'));assert.equal(saved.id,payload.ownerPilotControl.engineeringSequences[0].id);assert.equal(saved.runtime,JSON.stringify(payload.ownerPilotControl.engineeringSequences[0].runtime));assert.equal(saved.registrationRequested,true);assert.match(h.get('opsEngineeringTrialResult').textContent,/Selection recovered; no execution authority/);assert.equal(h.get('opsObjective').value,'Read owned internal records.');});
for(const mode of ['multiple','expired','attempted','wrong-scope','active','malformed','nested-release','missing-cleanup'])test('sequence selection recovery denies '+mode+' without storage or POST',async()=>{const payload=recoveryPayload(),row=payload.ownerPilotControl.engineeringSequences[0];if(mode==='multiple')payload.ownerPilotControl.engineeringSequences.push(structuredClone(row));if(mode==='expired')row.expiresAt=Date.now()-1;if(mode==='attempted')row.attempts=[{}];if(mode==='wrong-scope')payload.operatingSystem.scopeIdentity.ownerHash='0'.repeat(64);if(mode==='active')payload.ownerPilotControl.approvals=[{status:'active',leaseUntil:0}];if(mode==='malformed')row.remainingMicros={private:'DO_NOT_RENDER'};if(mode==='nested-release')row.runtime.release.digest={private:'DO_NOT_RENDER'};if(mode==='missing-cleanup')payload.ownerPilotControl.cleanupStatus.ready=false;const local=recoveryPayload().operatingSystem,h=harness(async()=>({__json:true,value:payload}));h.update(local);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.storage.has('callercore-engineering-development-4usd-v1'),false);assert(h.calls.every(x=>x.method==='GET'));assert(!h.get('opsEngineeringTrialResult').textContent.includes('DO_NOT_RENDER'));});
for(const key of ['callercore-engineering-development-4usd-v1','callercore-engineering-development-attempt-v1'])test('sequence selection recovery never overwrites existing or malformed '+key,async()=>{const payload=recoveryPayload(),storage=new Map([[key,'NOT_VALID_JSON']]),h=harness(async()=>({__json:true,value:payload}),storage);h.update(payload.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(storage.get(key),'NOT_VALID_JSON');assert.equal(h.calls.length,0);});
