test('cache inserted between GETs is preserved and prevents recovery overwrite',async()=>{const payload=recoveryPayload();let n=0;const h=harness(async()=>{if(++n===2)h.storage.set('callercore-engineering-trial-once-v1','INSERTED_PENDING');return{__json:true,value:payload};});h.update(payload.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.storage.get('callercore-engineering-trial-once-v1'),'INSERTED_PENDING');assert.equal(h.storage.has('callercore-engineering-development-4usd-v1'),false);});
for(const kind of ['network','json'])test('recovery '+kind+' failure never writes cache or retries',async()=>{const payload=recoveryPayload(),h=harness(async()=>{if(kind==='network')throw Error('PRIVATE_MUST_NOT_RENDER');return{__jsonFailure:true};});h.update(payload.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.storage.has('callercore-engineering-development-4usd-v1'),false);assert.equal(h.calls.length,1);assert(!h.get('opsEngineeringTrialResult').textContent.includes('PRIVATE_MUST_NOT_RENDER'));});
for(const [name,change]of Object.entries({executionAuthority:x=>x.executionAuthorized=true,contract:x=>x.cleanupContractSatisfied=false,blockers:x=>x.blockers=[{}],revocation:x=>x.revocationTargets=[{}],unknownBlocker:x=>x.unattributedBlockers=1,liveGrant:x=>x.ownedGrants=[{revoked:false}],missingGrants:x=>delete x.ownedGrants}))test('contradictory cleanup '+name+' denies local sequence recovery',async()=>{const payload=recoveryPayload();change(payload.ownerPilotControl.cleanupStatus);const h=harness(async()=>({__json:true,value:payload}));h.update(payload.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.storage.has('callercore-engineering-development-4usd-v1'),false);assert(h.calls.every(x=>x.method==='GET'));});
function admissionFixture(reply){const payload=recoveryPayload(),v=payload.operatingSystem,row=payload.ownerPilotControl.engineeringSequences[0];v.runtime=structuredClone(row.runtime);const objective=require('../lib/agent-operations-engineering-provider-v2').DEVELOPMENT_TRIAL.objective;v.organization.implementationPreparation={profile:'engineering-implementation-v1',objective};v.plans=[{...plan(),id:'op_readonly_admission',engineeringProfile:'engineering-implementation-v1',objective,deadline:Date.now()+600000,runtime:structuredClone(v.runtime),tasks:Array.from({length:5},(_,i)=>({...plan().tasks[0],id:'task'+i,attempts:[]}))}];const storage=new Map([['callercore-engineering-development-4usd-v1',JSON.stringify({scope:v.scopeIdentity,runtime:JSON.stringify(v.runtime),id:row.id,registrationRequested:true})]]),h=harness(reply,storage);h.update(v);return{h,v,row,storage};}
function admissionManifest(f){return{executionAuthorized:false,planId:f.v.plans[0].id,expectedRevision:1,approval:{sourceCommit:f.v.runtime.sourceCommit,contractHash:f.v.runtime.release.digest,deploymentOrigin:f.v.runtime.origin,ownerHash:f.v.scopeIdentity.ownerHash,expiresAt:f.v.plans[0].deadline,sequence:{id:f.row.id,attempt:1},proposalOnly:true,ownerAcceptance:false,publicationAuthorized:false,model:'gpt-6.1-sol',reasoning:'medium',maxCalls:5,maxTokenCountRequests:5,maxInputTokens:60000,maxOutputTokens:20000,maxMicros:1000000}};}
test('explicit admission check calls only status and manifest, displays bounded hash/limits and saves no approval',async()=>{let f;f=admissionFixture(async body=>({__engineering:true,value:body.action.endsWith('sequenceStatus')?{}:admissionManifest(f)}));const before=[...f.storage];await f.h.get('opsEngineeringDevelopmentPreset').emit('click');await f.h.get('opsEngineeringAdmissionCheck').emit('click');assert.deepEqual(f.h.calls.map(x=>x.action),['operations-engineering-activation-sequenceStatus','operations-engineering-activation-trial-manifest']);assert.deepEqual([...f.storage],before);const shown=JSON.parse(f.h.get('opsEngineeringTrialResult').textContent);assert.equal(shown.approvalCreated,false);assert.equal(shown.executionAuthorized,false);assert.match(shown.proposalHash,/^[a-f0-9]{64}$/);assert(!f.h.calls.some(x=>/sequenceRegister|activation-prepare|activation-activate|activation-run/.test(x.action)));});
for(const phase of ['sequenceStatus','trial-manifest'])test('admission check exposes only safe '+phase+' denial without retry',async()=>{const f=admissionFixture(async body=>body.action.endsWith(phase)?{__response:true,status:409,body:{code:'ENG_SEQUENCE_CLEANUP',error:'PRIVATE_SECRET'}}:{__engineering:true,value:{}});await f.h.get('opsEngineeringDevelopmentPreset').emit('click');await f.h.get('opsEngineeringAdmissionCheck').emit('click');const text=f.h.get('opsEngineeringTrialResult').textContent;assert(text.includes(phase));assert(text.includes('ENG_SEQUENCE_CLEANUP'));assert(!text.includes('PRIVATE_SECRET'));assert.equal(f.h.calls.length,phase==='sequenceStatus'?1:2);assert.equal(f.storage.has('callercore-engineering-development-attempt-v1'),false);});
test('admission network errors and changed source fence cannot create approval or expose raw exception',async()=>{for(const mode of ['network','fence']){let f;f=admissionFixture(async()=>{if(mode==='network')throw Error('PRIVATE_SECRET');f.h.update(state(2,{workspaceHash:'0'.repeat(64)}));return{__engineering:true,value:{}};});await f.h.get('opsEngineeringDevelopmentPreset').emit('click');await f.h.get('opsEngineeringAdmissionCheck').emit('click');assert.equal(f.h.calls.length,1);assert(!f.h.get('opsEngineeringTrialResult').textContent.includes('PRIVATE_SECRET'));assert.equal(f.storage.has('callercore-engineering-development-attempt-v1'),false);}});
test('admission check refuses stale target selection and any cached approval before request',async()=>{for(const mode of ['runtime','approval']){const f=admissionFixture(async()=>{throw Error('must not request');});if(mode==='runtime')f.v.runtime.deploymentId='dpl_other';else f.storage.set('callercore-engineering-trial-once-v1','UNCERTAIN');f.h.update(f.v);await f.h.get('opsEngineeringDevelopmentPreset').emit('click');await f.h.get('opsEngineeringAdmissionCheck').emit('click');assert.equal(f.h.calls.length,0);}});
for(const code of ['ENG_CONTROL_AUDIT_HEADROOM','ENG_CONTROL_BUDGET','ENG_CONTROL_SEQUENCE','ENG_SEQUENCE_CLEANUP'])test('admission check preserves exact safe denial '+code+' without approval or retry',async()=>{const f=admissionFixture(async body=>body.action.endsWith('sequenceStatus')?{__engineering:true,value:{}}:{__response:true,status:409,body:{code,error:'PRIVATE_MUST_NOT_RENDER'}});await f.h.get('opsEngineeringDevelopmentPreset').emit('click');await f.h.get('opsEngineeringAdmissionCheck').emit('click');assert(f.h.get('opsEngineeringTrialResult').textContent.includes(code));assert(!f.h.get('opsEngineeringTrialResult').textContent.includes('PRIVATE_MUST_NOT_RENDER'));assert.equal(f.h.calls.length,2);assert.equal(f.storage.has('callercore-engineering-development-attempt-v1'),false);});
for(const mode of ['expired-manifest','beyond-task','authority-true','authority-missing','attempt-zero','attempt-object'])test('read-only admission rejects '+mode+' while preserving full Prepare gates',async()=>{let f;f=admissionFixture(async body=>{if(body.action.endsWith('sequenceStatus'))return{__engineering:true,value:{}};const m=admissionManifest(f);if(mode==='expired-manifest')m.approval.expiresAt=Date.now()-1;if(mode==='beyond-task')m.approval.expiresAt=f.v.plans[0].deadline+1;if(mode==='authority-true')m.executionAuthorized=true;if(mode==='authority-missing')delete m.executionAuthorized;if(mode==='attempt-zero')m.approval.sequence.attempt=0;if(mode==='attempt-object')m.approval.sequence.attempt={private:'DO_NOT_RENDER'};return{__engineering:true,value:m};});await f.h.get('opsEngineeringDevelopmentPreset').emit('click');await f.h.get('opsEngineeringAdmissionCheck').emit('click');assert(!f.h.get('opsEngineeringTrialResult').textContent.includes('read-only-admission-path-checked-full-approval-validation-pending'));assert(!f.h.get('opsEngineeringTrialResult').textContent.includes('DO_NOT_RENDER'));assert.equal(f.h.calls.length,2);assert.equal(f.storage.has('callercore-engineering-development-attempt-v1'),false);});

function usedRecoveryPayload(){
 const p=recoveryPayload(),r=p.ownerPilotControl.engineeringSequences[0],base=r.enrollments[0];r.remainingMicros=1200000;r.retainedMicros=2800000;
 for(let i=1;i<5;i++)r.enrollments.push({...structuredClone(base),ordinal:i+1,previousHash:r.enrollments[i-1].hash,hash:String(i+4).repeat(64),runtime:{...structuredClone(base.runtime),deploymentId:'dpl_successor'+i}});
 for(let i=0;i<4;i++){const h=String(i+1).repeat(32),a={attempt:i+1,approvalId:'pilot_'+h,workflowId:'wf_'+h,planId:'op_'+h,approvalHash:'a'.repeat(64),enrollmentHash:r.enrollments[i+1].hash,claimedAt:Date.now()-100};r.attempts.push(a);p.ownerPilotControl.approvals.push({id:a.approvalId,status:'revoked',leaseUntil:0});p.ownerPilotControl.workflows.push({id:a.workflowId,status:'blocked',leaseUntil:0,attempts:[{closed:true}]});}return p;
}
function uncappedRecoveryPayload(){const p=usedRecoveryPayload(),r=p.ownerPilotControl.engineeringSequences[0];r.attemptPolicy=structuredClone(require('../lib/agent-operations-engineering-sequence').ATTEMPT_POLICY);for(let i=r.attempts.length;i<12;i++){const id=(i+1).toString(16).padStart(32,'0'),a={attempt:i+1,approvalId:'pilot_'+id,workflowId:'wf_'+id,planId:'op_'+id,approvalHash:'b'.repeat(64),enrollmentHash:r.enrollments.at(-1).hash,claimedAt:Date.now()-100};r.attempts.push(a);p.ownerPilotControl.approvals.push({id:a.approvalId,status:'revoked',leaseUntil:0});p.ownerPilotControl.workflows.push({id:a.workflowId,status:'blocked',leaseUntil:0,attempts:[{closed:true}]});}return p;}
test('development local closed-attempt archive can pass twenty without deleting prior receipts',async()=>{const h=harness(async()=>({__engineering:true,value:{status:'revoked',leaseUntil:0}})),v=state(),id='owner-phase-d-engineering-4usd-v1',key='callercore-engineering-development-attempt-v1',history=Array.from({length:20},(_,i)=>({historical:i})),saved={scope:v.scopeIdentity,input:{planId:'op_closed',approval:{...trialApproval(),countPricing:{authorizationId:id}}},requested:true};v.organization.implementationPreparation={profile:'engineering-implementation-v1',objective:require('../lib/agent-operations-implementation').OBJECTIVE};h.update(v);await h.get('opsEngineeringDevelopmentPreset').emit('click');h.storage.set(key,JSON.stringify(saved));h.storage.set(key+'-history',JSON.stringify(history));await h.get('opsEngineeringTrialRevoke').emit('click');assert.equal(h.storage.has(key),false);const out=JSON.parse(h.storage.get(key+'-history'));assert.deepEqual(out.slice(0,20),history);assert.deepEqual(out[20].saved,saved);assert.equal(h.calls.length,1);assert(h.calls[0].action.endsWith('-revoke'));});
test('current server attempt policy permits read-only recovery beyond ten while preserving original records',async()=>{const p=uncappedRecoveryPayload(),before=JSON.stringify(p),h=harness(async()=>({__json:true,value:structuredClone(p)}));h.update(p.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(JSON.parse(h.storage.get('callercore-engineering-development-4usd-v1')).id,p.ownerPilotControl.engineeringSequences[0].id);assert.equal(h.calls.length,2);assert(h.calls.every(c=>c.method==='GET'));assert.equal(JSON.stringify(p),before);});
for(const fault of ['missing','wrong-version','enforced','extra-key'])test('uncapped recovery requires exact current server policy: '+fault,async()=>{const p=uncappedRecoveryPayload(),r=p.ownerPilotControl.engineeringSequences[0];if(fault==='missing')delete r.attemptPolicy;if(fault==='wrong-version')r.attemptPolicy.version='forged';if(fault==='enforced')r.attemptPolicy.limitEnforced=true;if(fault==='extra-key')r.attemptPolicy.execute=true;const h=harness(async()=>({__json:true,value:structuredClone(p)}));h.update(p.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.storage.has('callercore-engineering-development-4usd-v1'),false);assert(h.calls.every(c=>c.method==='GET'));});
test('used sequence recovery selects latest verified enrollment with two GETs only and preserves original history',async()=>{const p=usedRecoveryPayload(),before=JSON.stringify(p),h=harness(async()=>({__json:true,value:structuredClone(p)}));h.update(p.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');const saved=JSON.parse(h.storage.get('callercore-engineering-development-4usd-v1'));assert.equal(saved.runtime,JSON.stringify(p.ownerPilotControl.engineeringSequences[0].enrollments.at(-1).runtime));assert.equal(saved.id,p.ownerPilotControl.engineeringSequences[0].id);assert.equal(h.calls.length,2);assert(h.calls.every(x=>x.method==='GET'));assert.equal(h.storage.size,1);assert.equal(JSON.stringify(p),before);});
for(const mode of ['ordinal','previous','duplicate-enrollment','base-binding','base-runtime','unknown-enrollment','duplicate-plan','duplicate-approval','duplicate-workflow','attempt-ordinal','attempt-hash','attempt-time','missing-approval','missing-workflow','open-attempt','unrevoked','insufficient','accounting','changed-second'])test('used recovery denies '+mode+' without authority mutation',async()=>{const p=usedRecoveryPayload(),r=p.ownerPilotControl.engineeringSequences[0];if(mode==='ordinal')r.enrollments[1].ordinal=5;if(mode==='previous')r.enrollments[2].previousHash='f'.repeat(64);if(mode==='duplicate-enrollment')r.enrollments[1].hash=r.enrollments[0].hash;if(mode==='base-binding')r.enrollments[0].bindingHash='f'.repeat(64);if(mode==='base-runtime')r.enrollments[0].runtime.deploymentId='dpl_wrong';if(mode==='unknown-enrollment')r.attempts[0].enrollmentHash='f'.repeat(64);for(const [name,k]of [['duplicate-plan','planId'],['duplicate-approval','approvalId'],['duplicate-workflow','workflowId']])if(mode===name)r.attempts[1][k]=r.attempts[0][k];if(mode==='attempt-ordinal')r.attempts[0].attempt=2;if(mode==='attempt-hash')r.attempts[0].approvalHash='PRIVATE';if(mode==='attempt-time')r.attempts[0].claimedAt=r.expiresAt;if(mode==='missing-approval')p.ownerPilotControl.approvals.shift();if(mode==='missing-workflow')p.ownerPilotControl.workflows.shift();if(mode==='open-attempt')p.ownerPilotControl.workflows[0].attempts[0].closed=false;if(mode==='unrevoked')p.ownerPilotControl.approvals[0].status='consumed';if(mode==='insufficient')r.remainingMicros=999999;if(mode==='accounting')r.retainedMicros++;let n=0;const h=harness(async()=>{if(++n===2&&mode==='changed-second')r.attempts[0].approvalHash='b'.repeat(64);return{__json:true,value:structuredClone(p)};});h.update(p.operatingSystem);await h.get('opsEngineeringSequenceRecover').emit('click');assert.equal(h.storage.has('callercore-engineering-development-4usd-v1'),false);assert(h.calls.every(x=>x.method==='GET'));assert(!h.get('opsEngineeringTrialResult').textContent.includes('PRIVATE'));});
